import{_ as e,o as n,c as l,a5 as d}from"./chunks/framework.CsGesDJn.js";const y=JSON.parse('{"title":"Test — Create Agency with Personal and Business Mode (FR 3.4.3.B)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/personal-agency-transition/test.md","filePath":"feature/agency-workspace/personal-agency-transition/test.md"}'),a={name:"feature/agency-workspace/personal-agency-transition/test.md"};function o(s,t,g,i,c,r){return n(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="test-—-create-agency-with-personal-and-business-mode-fr-3-4-3-b" tabindex="-1">Test — Create Agency with Personal and Business Mode (FR 3.4.3.B) <a class="header-anchor" href="#test-—-create-agency-with-personal-and-business-mode-fr-3-4-3-b" aria-label="Permalink to &quot;Test — Create Agency with Personal and Business Mode (FR 3.4.3.B)&quot;">​</a></h1><p>&gt; Danh mục Test Case kiểm thử chức năng Tạo Agency hỗ trợ chế độ Cá nhân (Personal Mode) và Doanh nghiệp (Business Mode), suy từ Acceptance Criteria trong <a href="./report3_spec.html">report3_spec.md</a>.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Test Case ID</th><th style="text-align:left;">Mô tả kịch bản (Input / Điều kiện)</th><th style="text-align:left;">AC liên quan</th><th style="text-align:left;">Kết quả mong đợi</th><th style="text-align:left;">Loại kiểm thử</th><th style="text-align:left;">Trạng thái</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>TC-PERS-01</strong></td><td style="text-align:left;">Tạo Agency với <code>type = &#39;PERSONAL&#39;</code> đầy đủ thông tin hợp lệ</td><td style="text-align:left;">AC-02, AC-03</td><td style="text-align:left;">• HTTP <code>201 Created</code>.&lt;br/&gt;• Bản ghi <code>agencies</code> có <code>type = &#39;PERSONAL&#39;</code>.&lt;br/&gt;• Bản ghi <code>workspaces</code> cá nhân được auto-create với cùng tên/branding.&lt;br/&gt;• <code>workspace_members</code> tạo cho currentUser với role <code>MANAGER</code>.&lt;br/&gt;• Response trả về <code>defaultWorkspaceId</code> khác null.</td><td style="text-align:left;">Happy Path (Backend)</td><td style="text-align:left;">Đã sẵn sàng test</td></tr><tr><td style="text-align:left;"><strong>TC-PERS-02</strong></td><td style="text-align:left;">Tạo Agency với <code>type = &#39;PERSONAL&#39;</code> tối giản (chỉ có <code>name</code> và <code>type</code>)</td><td style="text-align:left;">AC-02</td><td style="text-align:left;">• HTTP <code>201 Created</code>.&lt;br/&gt;• Agency và Workspace đều được tạo thành công với các trường tùy chọn mang giá trị null.&lt;br/&gt;• <code>defaultWorkspaceId</code> trả về hợp lệ.</td><td style="text-align:left;">Happy Path (Backend)</td><td style="text-align:left;">Đã sẵn sàng test</td></tr><tr><td style="text-align:left;"><strong>TC-PERS-03</strong></td><td style="text-align:left;">Tạo Agency với <code>type = &#39;BUSINESS&#39;</code></td><td style="text-align:left;">AC-01</td><td style="text-align:left;">• HTTP <code>201 Created</code>.&lt;br/&gt;• Bản ghi <code>agencies</code> có <code>type = &#39;BUSINESS&#39;</code>.&lt;br/&gt;• <strong>Không</strong> tự động tạo Workspace (<code>defaultWorkspaceId == null</code>).&lt;br/&gt;• Chuyển hướng người dùng về trang chi tiết Agency <code>/agency/{id}</code>.</td><td style="text-align:left;">Happy Path (Backend)</td><td style="text-align:left;">Đã sẵn sàng test</td></tr><tr><td style="text-align:left;"><strong>TC-PERS-04</strong></td><td style="text-align:left;">Tạo Agency nhưng không truyền <code>type</code> (Tương thích ngược)</td><td style="text-align:left;">AC-06</td><td style="text-align:left;">• Server tự động gán giá trị mặc định <code>type = &#39;BUSINESS&#39;</code>.&lt;br/&gt;• Hoạt động chuẩn như phiên bản cũ.</td><td style="text-align:left;">Regression / Backward Compat</td><td style="text-align:left;">Đã sẵn sàng test</td></tr><tr><td style="text-align:left;"><strong>TC-PERS-05</strong></td><td style="text-align:left;">Nhập <code>name</code> rỗng hoặc chỉ có khoảng trắng</td><td style="text-align:left;">BR-AGENCY-01</td><td style="text-align:left;">• HTTP <code>400 VALIDATION_ERROR</code> (do <code>@NotBlank</code>).&lt;br/&gt;• Không có Agency hay Workspace nào được lưu vào DB.</td><td style="text-align:left;">Validation Error</td><td style="text-align:left;">Đã sẵn sàng test</td></tr><tr><td style="text-align:left;"><strong>TC-PERS-06</strong></td><td style="text-align:left;">Mã màu <code>brandColor</code> quá 9 ký tự hoặc <code>tagline</code> quá 140 ký tự</td><td style="text-align:left;">BR-AGENCY-02</td><td style="text-align:left;">• HTTP <code>400 VALIDATION_ERROR</code>.&lt;br/&gt;• Báo lỗi trường tương ứng.</td><td style="text-align:left;">Validation Error</td><td style="text-align:left;">Đã sẵn sàng test</td></tr><tr><td style="text-align:left;"><strong>TC-PERS-07</strong></td><td style="text-align:left;">Không kèm JWT Token hoặc Token hết hạn</td><td style="text-align:left;">BR-AUTH</td><td style="text-align:left;">• HTTP <code>401 UNAUTHORIZED</code>.&lt;br/&gt;• Request bị chặn tại Gateway/Security Filter.</td><td style="text-align:left;">Security Error</td><td style="text-align:left;">Đã sẵn sàng test</td></tr><tr><td style="text-align:left;"><strong>TC-PERS-08</strong></td><td style="text-align:left;">Lỗi xảy ra khi lưu Workspace (Kiểm tra Rollback Transaction)</td><td style="text-align:left;">AC-05</td><td style="text-align:left;">• Nếu lưu Workspace gặp sự cố, giao dịch <code>@Transactional</code> rollback toàn bộ.&lt;br/&gt;• Bản ghi Agency <strong>không</strong> tồn tại trong database (không sinh orphan record).</td><td style="text-align:left;">Reliability / Atomicity</td><td style="text-align:left;">Đã sẵn sàng test</td></tr><tr><td style="text-align:left;"><strong>TC-PERS-09</strong></td><td style="text-align:left;">Frontend: Trải nghiệm người dùng khi tạo Personal Agency</td><td style="text-align:left;">AC-03</td><td style="text-align:left;">• Ngay sau khi API trả về thành công, Client tự động cập nhật <code>activeWorkspace</code>.&lt;br/&gt;• Trình duyệt điều hướng thẳng tới <code>/workspaces/{defaultWorkspaceId}/dashboard</code>.</td><td style="text-align:left;">E2E Frontend</td><td style="text-align:left;">Đã sẵn sàng test</td></tr><tr><td style="text-align:left;"><strong>TC-PERS-10</strong></td><td style="text-align:left;">Frontend: Kiểm tra Sidebar khi đang chọn Personal Agency</td><td style="text-align:left;">AC-04</td><td style="text-align:left;">• Sidebar <strong>ẩn</strong> hoàn toàn các mục: Khách hàng, Hồ sơ khách hàng, Lời mời khách hàng, Cổng khách hàng, Phân quyền vai trò.&lt;br/&gt;• Chỉ hiển thị các công cụ sáng tạo (Viết bài, Calendar, Thư viện, Đăng bài) và Báo cáo.</td><td style="text-align:left;">UI / Access Control</td><td style="text-align:left;">Đã sẵn sàng test</td></tr><tr><td style="text-align:left;"><strong>TC-PERS-11</strong></td><td style="text-align:left;">Nâng cấp Agency từ <code>PERSONAL</code> lên <code>BUSINESS</code></td><td style="text-align:left;">BR-PERSONAL-06</td><td style="text-align:left;">• Gọi <code>PATCH /api/v1/agencies/{id}/upgrade-type</code> với <code>type = &#39;BUSINESS&#39;</code>.&lt;br/&gt;• Agency chuyển sang <code>BUSINESS</code>, Sidebar tự động mở lại các mục Client và Member roles.</td><td style="text-align:left;">Feature Toggle / Upgrade</td><td style="text-align:left;">Đã sẵn sàng test</td></tr></tbody></table><hr><h2 id="tieu-chi-hoan-thanh-definition-of-done-dod" tabindex="-1">Tiêu Chí Hoàn Thành (Definition of Done - DoD) <a class="header-anchor" href="#tieu-chi-hoan-thanh-definition-of-done-dod" aria-label="Permalink to &quot;Tiêu Chí Hoàn Thành (Definition of Done - DoD)&quot;">​</a></h2><ol><li>100% các Test Case trên pass cả Unit Test (<code>AgencyServiceImplTest</code>) và Manual Test trên Web UI.</li><li>Không phát sinh hồi quy (regression) đối với các Agency Doanh nghiệp hiện có.</li><li>Không có lỗi rò rỉ quyền (Access Leak) hoặc hiển thị nhầm menu B2B trong chế độ Cá nhân.</li></ol>',6)])])}const f=e(a,[["render",o]]);export{y as __pageData,f as default};
